import{_ as a,c as n,o as t,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const i="/media-docs/assets/image-20251112162044982.Bu156hsE.png",o="/media-docs/assets/image-20251112162219069.BKwZrxkO.png",l="/media-docs/assets/image-20251112163108239.CR13TwY0.png",s="/media-docs/assets/image-20251112164504219.BWWZYqAQ.png",c="/media-docs/assets/image-20251112164604151.CJXpN460.png",f=JSON.parse('{"title":"LV020-多Lane分发与合并","description":null,"frontmatter":{"title":"LV020-多Lane分发与合并","date":"2025-11-12T11:22:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/mipi/csi/126b1458006c3d34823b6c19","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-12T11:22:36.979Z","fulluuid":"4823b6c190d147e2bab92f51040b4134","useduuid":"4823b6c19"}},"headers":[],"relativePath":"sdoc/mipi/csi/126b1458006c3d34823b6c19.md","filePath":"sdoc/15-MIPI/10-CSI/LV020-多Lane分发与合并.md","lastUpdated":1767537778000}'),p={name:"sdoc/mipi/csi/126b1458006c3d34823b6c19.md"};function d(L,e,u,h,m,b){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="lv020-多lane分发与合并" tabindex="-1">LV020-多Lane分发与合并 <a class="header-anchor" href="#lv020-多lane分发与合并" aria-label="Permalink to &quot;LV020-多Lane分发与合并&quot;">​</a></h1><blockquote><p><a href="https://picture.iczhiku.com/resource/eetop/wYkfSsAFZOeaJvXx.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2)</a>——8 Multi-Lane Distribution and Merging</p></blockquote><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>CSI-2 是一个 lane 可扩展的规范。CSI-2 是一个可扩展 Lane 的规范。对带宽有更高要求、需要多于一条 Lane 的应用，或者哪些想要避免高时钟频率的应用，都能通过扩展数据路径到更多条 Lane 来获得近似线性增长的峰值带宽。多条 Lane 的情况下，更高层的字节流数据和每条 Lane 上传输的串行 bit 或符号（symbol）流的映射关系有明确地定义，以便 host 侧处理器和外设之间在使用多条 Lane 的时候能够兼容。</p><p>概念上讲，在 PHY 和更高层次的功能层之间，有一个中间层用来处理多 Lane 配置。CSI-2 的发送器中有一个 LDF（Lane Distribution Function），它从 LLP（Low Level Protocol）接收数据包，并且将数据包的字节分发到 N 条 Lane 上，每条 Lane 都是一个独立的物理层逻辑单元和传输电路。CSI-2 接收器中有一个 LMF（Lane Merging Function），它从 N 条 Lane 中收集字节数据，并且将多 Lane 的字节数据合并为完整的数据包，交给接收器的 LLP 层的分解器（decomposer）处理。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+i+'" alt="image-20251112162044982" style="width:95%;height:auto;"></td><td align="center" style="border:none;"><img src="'+o+'" alt="image-20251112162219069" style="width:100%;height:auto;"></td></tr></tbody></table><p>Lane 数据分发器（Distributor）可以处理任意字节长度的传输，可以缓冲 N * b 字节（N：Lane 的数量，D-PHY 的 b = 1， C-PHY 的 b = 2）。然后在 N 条 Lane 上并行地发送这组 N * b 个字节的数据，接收方每 Lane 接收 b 个字节。在发送数据前，所有 Lane 会并行地发起 SoT 序列来通知它们连接的接收单元开始接收包的首字节。在 SoT 之后，Lane 会并行地发送一组组的数据包的后续字节，这些分组遵循 round-robin 流程挨个轮询。</p><h2 id="二、d-phy-物理层的-lane-数据分发" tabindex="-1">二、D-PHY 物理层的 Lane 数据分发 <a class="header-anchor" href="#二、d-phy-物理层的-lane-数据分发" aria-label="Permalink to &quot;二、D-PHY 物理层的 Lane 数据分发&quot;">​</a></h2><h3 id="_1-d-phy-2-lane-数据分发" tabindex="-1">1. D-PHY 2-Lane 数据分发 <a class="header-anchor" href="#_1-d-phy-2-lane-数据分发" aria-label="Permalink to &quot;1. D-PHY 2-Lane 数据分发&quot;">​</a></h3><p>2-Lane 系统（图 22）：数据包的字节 0 进入 Lane 1，字节 1 进入 Lane 2，字节 2 进入 Lane 1，字节 3 进入 Lane 2，字节 4 进入 Lane 1，以此类推。</p><p><img src="'+l+'" alt="image-20251112163108239"></p><h3 id="_2-d-phy-3-lane-数据分发" tabindex="-1">2. D-PHY 3-Lane 数据分发 <a class="header-anchor" href="#_2-d-phy-3-lane-数据分发" aria-label="Permalink to &quot;2. D-PHY 3-Lane 数据分发&quot;">​</a></h3><blockquote><p><a href="https://picture.iczhiku.com/resource/eetop/wYkfSsAFZOeaJvXx.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2)</a>——Figure 23 Three Lane Multi-Lane Example</p></blockquote><h3 id="_3-d-phy-4-lane-数据分发" tabindex="-1">3. D-PHY 4-Lane 数据分发 <a class="header-anchor" href="#_3-d-phy-4-lane-数据分发" aria-label="Permalink to &quot;3. D-PHY 4-Lane 数据分发&quot;">​</a></h3><blockquote><p><a href="https://picture.iczhiku.com/resource/eetop/wYkfSsAFZOeaJvXx.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2)</a>——Figure 24 Four Lane Multi-Lane Example</p></blockquote><h2 id="三、multi-lanes-互通性" tabindex="-1">三、Multi-Lanes 互通性 <a class="header-anchor" href="#三、multi-lanes-互通性" aria-label="Permalink to &quot;三、Multi-Lanes 互通性&quot;">​</a></h2><p>当使用多于1条数据Lane的时候，Lane数据分发和合并层要能通过CCI接口进行重配置。</p><p>一个N条数据Lane的接收器要和一个M条数据Lane的发送器连接，当多于1条数据Lane被使用时，需要通过CCI配置CSI-2发送器和接收器里的Lane分发和合并层。</p><p>因此，如果M &lt;= N，N条数据Lane的接收器能够和此发送器工作，使用M条数据Lane。如下图所示：</p><p><img src="'+s+'" alt="image-20251112164504219"></p><p>这种情况下，没有性能损失，因为发送器的所有Lane都使用到了，接收器也有足够的数据Lane来匹配发送器。</p><p>如果M&gt;N，M条数据Lane的发送器能够和此接收器工作，使用N条数据Lane。如下图所示：</p><p><img src="'+c+'" alt="image-20251112164604151"></p><p>这种情况下，由于发送器不能使用所有数据Lane，因此可能会有性能损失（是否有损失要看分辨率和帧率之类的因素），接收器必发送器的数据Lane要少。</p>',24)])])}const g=a(p,[["render",d]]);export{f as __pageData,g as default};
